package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.*;
public class Pb01Block extends BaseEntityBlock{
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final BooleanProperty LIT=BlockStateProperties.LIT;public static final IntegerProperty PART=IntegerProperty.create("part",0,15),BANK=IntegerProperty.create("bank",0,15),PAGE=IntegerProperty.create("page",0,(Pb01Geometry.MODEL.bodyVariants.length-1)/256),DOOR_BANK=IntegerProperty.create("bank",0,(Pb01Geometry.MODEL.doorVariants.length-1)/16),STEP=IntegerProperty.create("door",0,21);public static final ThreadLocal<Boolean>MUTATING=ThreadLocal.withInitial(()->false);public final boolean door;
 public Pb01Block(Properties p,boolean moving){super(p);door=moving;var s=stateDefinition.any().setValue(FACING,Direction.NORTH).setValue(PART,0).setValue(moving?DOOR_BANK:BANK,0);s=moving?s.setValue(STEP,0):s.setValue(PAGE,0).setValue(LIT,true);registerDefaultState(s);}
 @Override protected com.mojang.serialization.MapCodec<?extends BaseEntityBlock>codec(){return simpleCodec(p->new Pb01Block(p,false));}
 @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(FACING);if(getClass()==Pb01DoorBlock.class)b.add(PART,DOOR_BANK,STEP);else b.add(PART,BANK,PAGE,LIT);}
 // Small radix properties avoid Minecraft allocating quadratic neighbour tables for thousands of values.
 public static int part(BlockState s){boolean moving=((Pb01Block)s.getBlock()).door;return s.getValue(PART)+16*s.getValue(moving?DOOR_BANK:BANK)+(moving?0:256*s.getValue(PAGE));}
 public static BlockState part(BlockState s,int value){boolean moving=((Pb01Block)s.getBlock()).door;s=s.setValue(PART,value%16).setValue(moving?DOOR_BANK:BANK,(value/16)%16);return moving?s:s.setValue(PAGE,value/256);}
 public static BlockPos root(BlockPos p,BlockState s){var b=(Pb01Block)s.getBlock();return Ps01Geometry.root(p,s.getValue(FACING),Pb01Geometry.MODEL.variant(b.door,part(s)).cell());}
 public static Pb01BlockEntity main(Level l,BlockPos p,BlockState s){var r=root(p,s);return l.hasChunkAt(r)&&l.getBlockEntity(r)instanceof Pb01BlockEntity b?b:null;}
 @Override public BlockState getStateForPlacement(net.minecraft.world.item.context.BlockPlaceContext c){return defaultBlockState().setValue(FACING,Pb01Item.face(c.getPlayer(),c.getItemInHand()));}
 @Override public void setPlacedBy(Level l,BlockPos p,BlockState s,LivingEntity actor,ItemStack item){if(l.getBlockEntity(p)instanceof Pb01BlockEntity b){var n=DefenseItem.data(item);if(n.contains("BunkerState"))b.restore(n.getCompound("BunkerState"));b.id=java.util.UUID.randomUUID();if(b.owner==null&&actor!=null){b.owner=actor.getUUID();b.ownerName=actor.getScoreboardName();}if(l instanceof net.minecraft.server.level.ServerLevel sl){var team=sl.getScoreboard().getPlayersTeam(b.ownerName);b.team=team==null?"":team.getName();Pb01WorldData.get(sl).add(b);b.refresh();b.changed();}}}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player player,BlockHitResult hit){return interact(s,l,p,player,InteractionHand.MAIN_HAND,hit);}
 @Override protected net.minecraft.world.ItemInteractionResult useItemOn(ItemStack stack,BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){return interact(s,l,p,player,hand,hit).consumesAction()?net.minecraft.world.ItemInteractionResult.sidedSuccess(l.isClientSide):net.minecraft.world.ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 public InteractionResult interact(BlockState s,Level l,BlockPos p,Player player,InteractionHand hand,BlockHitResult hit){if(player.getItemInHand(hand).getItem()instanceof Pb01Item)return InteractionResult.PASS;var b=main(l,p,s);if(b==null)return InteractionResult.FAIL;if(l.isClientSide)return InteractionResult.SUCCESS;if(!(player instanceof net.minecraft.server.level.ServerPlayer sp)||!b.reachable(sp,hit))return InteractionResult.FAIL;var held=player.getItemInHand(hand);if(player.isShiftKeyDown()&&held.is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){b.remove(sp,!sp.isCreative(),false);return InteractionResult.CONSUME;}
  var at=Pb01Geometry.local(b.getBlockPos(),b.facing(),hit.getLocation());if(Pb01Geometry.MODEL.hitZone(at,b.mask(),b.doorStep())==10||at.x>1.15&&at.x<3&&at.z>3.25&&at.y>.25&&at.y<3){b.toggle(sp);return InteractionResult.CONSUME;}var anchor=Pb01Geometry.MODEL.anchor(b.getBlockPos(),b.facing(),"DVT_Mount_Anchor");if(held.is(AddonItems.DVT01.get())&&anchor.distanceToSqr(hit.getLocation())<2.25){Pb01Dvt.install(b,sp,hand);return InteractionResult.CONSUME;}for(int i=0;i<Pb01Geometry.MODEL.seats.length;i++){var a=Pb01Geometry.MODEL.seats[i];if(Pb01Geometry.point(b.getBlockPos(),b.facing(),a[0],a[1],a[2]).distanceToSqr(hit.getLocation())<1.2&&b.health[11]>0){Pb01Seat.sit(b,sp,i);return InteractionResult.CONSUME;}}
  if(at.x> -3.8&&at.x< -3&&at.z>3.1&&at.y>1.1&&at.y<2.5){b.toggleLights(sp);return InteractionResult.CONSUME;}player.displayClientMessage(net.minecraft.network.chat.Component.translatable("pb01.info",b.ownerName,Math.round(b.health[10]),b.lights?"ON":"OFF"),true);return InteractionResult.CONSUME;
 }
 @Override public VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Pb01Geometry.MODEL.shape(s.getValue(FACING),door,part(s),door?s.getValue(STEP):0);}@Override public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return getShape(s,l,p,c);}@Override public VoxelShape getOcclusionShape(BlockState s,BlockGetter l,BlockPos p){return Shapes.empty();}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.INVISIBLE;}
 @Override public int getLightBlock(BlockState s,BlockGetter l,BlockPos p){return getShape(s,l,p,CollisionContext.empty()).clip(new Vec3(.5,2,.5),new Vec3(.5,-1,.5),BlockPos.ZERO)==null?0:15;}
 @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return !door&&part(s)==0?new Pb01BlockEntity(p,s):null;}@Override public <T extends BlockEntity>BlockEntityTicker<T>getTicker(Level l,BlockState s,BlockEntityType<T>t){return !l.isClientSide&&!door&&part(s)==0?createTickerHelper(t,AddonBlockEntities.PB01.get(),Pb01BlockEntity::tick):null;}
 @Override public BlockState playerWillDestroy(Level l,BlockPos p,BlockState s,Player actor){if(!l.isClientSide&&actor instanceof net.minecraft.server.level.ServerPlayer sp){var b=main(l,p,s);if(b!=null)b.remove(sp,!sp.isCreative(),false);}return super.playerWillDestroy(l,p,s,actor);}
 @Override public void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(!l.isClientSide&&!MUTATING.get()&&!s.is(next.getBlock())){var b=main(l,p,s);if(b!=null)b.remove(null,false,!l.restoringBlockSnapshots);else if(l instanceof net.minecraft.server.level.ServerLevel sl)Pb01WorldData.get(sl).removeAt(sl,root(p,s));}super.onRemove(s,l,p,next,moving);}
 @Override public void neighborChanged(BlockState s,Level l,BlockPos p,Block block,BlockPos at,boolean moving){if(l.isClientSide||MUTATING.get()||!Pb01Config.terrain())return;var c=Pb01Geometry.MODEL.variant(door,part(s)).cell();if(c[1]==0&&at.equals(p.below())&&!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP)){var b=main(l,p,s);if(b!=null)b.checkSupport();}}
 // Explosion terrain callbacks must not dismantle a whole structure through one cell.
 // The server explosion event applies claim-checked, bounded structural durability wear.
 @Override public void onBlockExploded(BlockState state,Level level,BlockPos pos,Explosion explosion){}
 @Override public void onProjectileHit(Level l,BlockState s,BlockHitResult hit,net.minecraft.world.entity.projectile.Projectile projectile){super.onProjectileHit(l,s,hit,projectile);Ps01Compat.impact(projectile,hit);}
 @Override public BlockState rotate(BlockState s,Rotation r){return s.setValue(FACING,r.rotate(s.getValue(FACING)));}@Override public BlockState mirror(BlockState s,Mirror m){return rotate(s,m.getRotation(s.getValue(FACING)));}
}
